<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_roles(['pengguna']);require __DIR__.'/../../app/helpers/layout.php';render_start('Riwayat Pengajuan','Jejak status buku dan skripsi yang kamu kirim',$u);dashboard_nav('pengguna');render_mid('Riwayat Pengajuan','Status: Menunggu Verifikasi, Disetujui, Ditolak, atau Perlu Perbaikan',$u);$st=$pdo->prepare('SELECT sh.*,u.name processor FROM submission_history sh LEFT JOIN users u ON u.id=sh.processed_by WHERE sh.user_id=? ORDER BY sh.id DESC LIMIT 200');$st->execute([$u['id']]);$rows=$st->fetchAll();?><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Jenis</th><th>ID Data</th><th>Aksi</th><th>Catatan</th><th>Waktu</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(ucfirst($r['item_type']))?></td><td>#<?=e($r['item_id'])?></td><td><?=e(status_label($r['action']))?></td><td><?=e($r['note']??'—')?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="empty">Belum ada riwayat pengajuan.</td></tr><?php endif;?></tbody></table></div></div><?php render_end(); ?>
